<script setup lang="ts">
import { computed } from 'vue'

// OS logo: full-color official brand marks, no badge background.
// Sources: Devicon "original" (MIT, https://devicon.dev) for the 12 brands it
// covers; Simple Icons (CC0, https://simpleicons.org) single-color paths for
// the rest, filled with the brand color (or currentColor when the brand color
// is too dark for the dark theme / the mark is officially monochrome).
// openEuler uses its official symbol SVG from openeuler.org (cropped from the
// horizontal lockup). Anolis / OpenCloudOS / Kylin exist in no public icon
// library (verified 404 in Simple Icons, Devicon and Iconify logos) and no SVG
// exists on their official sites either, so their previous hand-drawn glyphs are
// kept as-is; their official PNGs are saved under ~/workspace/oslogo-assets.
// Alibaba Cloud Linux (alinux) uses the Simple Icons alibabacloud mark; it was
// previously mis-mapped to the Anolis glyph — the two distros are unrelated.
// Brand logos belong to their owners.
const props = withDefaults(
  defineProps<{
    os?: string
    distro?: string
    size?: number | string
  }>(),
  {
    os: '',
    distro: '',
    size: 28,
  }
)

export type OsBrand =
  | 'ubuntu'
  | 'debian'
  | 'centos'
  | 'redhat'
  | 'rocky'
  | 'almalinux'
  | 'fedora'
  | 'alpine'
  | 'arch'
  | 'suse'
  | 'kali'
  | 'amazon'
  | 'openeuler'
  | 'anolis'
  | 'alibabacloud'
  | 'opencloud'
  | 'kylin'
  | 'deepin'
  | 'mint'
  | 'freebsd'
  | 'windows'
  | 'macos'
  | 'linux'
  | 'other'

const brand = computed<OsBrand>(() => {
  const s = `${props.os || ''} ${props.distro || ''}`.toLowerCase()
  if (s.includes('ubuntu')) return 'ubuntu'
  if (s.includes('debian') || s.includes('raspbian')) return 'debian'
  if (s.includes('rocky')) return 'rocky'
  if (s.includes('alma')) return 'almalinux'
  if (s.includes('centos')) return 'centos'
  if (s.includes('rhel') || s.includes('red hat') || s.includes('redhat')) return 'redhat'
  if (s.includes('fedora')) return 'fedora'
  if (s.includes('alpine')) return 'alpine'
  if (s.includes('arch') || s.includes('manjaro') || s.includes('endeavour')) return 'arch'
  if (s.includes('suse') || s.includes('sles') || s.includes('opensuse')) return 'suse'
  if (s.includes('kali') || s.includes('parrot')) return 'kali'
  if (s.includes('amazon') || s.includes('amzn') || s.includes('aws')) return 'amazon'
  if (s.includes('openeuler') || s.includes('euler')) return 'openeuler'
  if (s.includes('alibaba') || s.includes('alinux') || s.includes('alibabacloud')) return 'alibabacloud'
  if (s.includes('anolis')) return 'anolis'
  if (s.includes('opencloud') || s.includes('tencent') || s.includes('tlinux')) return 'opencloud'
  if (s.includes('kylin') || s.includes('neokylin')) return 'kylin'
  if (s.includes('uos') || s.includes('deepin') || s.includes('uniontech')) return 'deepin'
  if (s.includes('mint')) return 'mint'
  if (s.includes('bsd') || s.includes('freebsd') || s.includes('openbsd')) return 'freebsd'
  if (s.includes('windows') || s.includes('win32') || s.includes('win64')) return 'windows'
  if (s.includes('darwin') || s.includes('mac') || s.includes('osx') || s.includes('apple')) return 'macos'
  if (s.includes('linux')) return 'linux'
  return 'other'
})
</script>

